/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/atendimento.defs.ts" enhancement="_blank"/>

/** Mesa disponível para início do atendimento, apresentada para seleção do garçom. */
export interface MesaDisponivel {
  id: string;
  code: string;
  details: {
    readonly disponivel: boolean;
  };
}

/** Identificação da mesa vinculada à comanda exibida no atendimento. */
export interface MesaReferencia {
  id: string;
  code: string;
}

/** Comanda aberta disponível para localização e seleção pelo garçom. */
export interface ComandaResumo {
  id: string;
  version: number;
  number: number;
  mesaId: string;
  status: 'open' | 'closed';
  mesa: MesaReferencia;
}

/** Item do cardápio apresentado para busca e escolha no lançamento. */
export interface ItemCardapioResumo {
  id: string;
  name: string;
  details: {
    precoVigente: string;
  };
}

/** Coleções independentes usadas para localizar a mesa, a comanda aberta e o item do pedido. */
export interface ContextoAtendimento {
  mesasDisponiveis: { items: MesaDisponivel[]; page: number; pageSize: number; hasMore: boolean };
  comandasAbertas: { items: ComandaResumo[]; page: number; pageSize: number; hasMore: boolean };
  itensCardapio: { items: ItemCardapioResumo[]; page: number; pageSize: number; hasMore: boolean };
}

/** Referência do cardápio da linha lançada, com o nome necessário para a conferência. */
export interface ItemCardapioDaComanda {
  id: string;
  name: string;
}

/** Linha da comanda, inclusive as canceladas, para conferência e correção. */
export interface ItemComandaAtendimento {
  id: string;
  version: number;
  comandaId: string;
  itemCardapioId: string;
  status: 'launched' | 'canceled';
  details: {
    quantidade: number;
    observacao?: string;
    precoUnitario: string;
    readonly valorTotal: string;
  };
  itemCardapio: ItemCardapioDaComanda;
}

/** Comanda selecionada, sua mesa, todos os itens e o subtotal calculado para o atendimento. */
export interface ComandaAtendimento {
  id: string;
  version: number;
  number: number;
  mesaId: string;
  status: 'open' | 'closed';
  mesa: MesaReferencia;
  details: {
    readonly subtotal: string;
  };
  itens: ItemComandaAtendimento[];
}

export interface AtendimentoContracts {
  /**
   * Finalidade: Carrega de uma vez o contexto inicial para o garçom localizar uma mesa disponível, uma comanda aberta ou um item do cardápio.
   * Entrada: Os pares mesasPage e mesasPageSize, comandasPage e comandasPageSize, itensPage e itensPageSize definem opcionalmente o trecho inicial de cada lista; na ausência deles, aplica os tamanhos padrão da página.
   * Processamento: Consulta somente mesas com disponibilidade calculada verdadeira, somente comandas em situação open e itens do cardápio ordenados por nome. Cada coleção é ordenada e paginada de forma independente, retornando hasMore sem transferir itens fora da tela. Não altera registros.
   * Saída: Retorna as três coleções já filtradas e no formato de localização, para abastecer a busca e a escolha inicial do contexto de atendimento.
   */
  'comandaRestaurante.atendimento.carregarAtendimento': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { contextoAtendimento: ContextoAtendimento };
    rules: [];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  /**
   * Finalidade: Atualiza a localização do atendimento quando o garçom pesquisa ou navega nas listas de mesa, comanda e cardápio.
   * Entrada: mesaTermo filtra o código de mesas disponíveis; comandaNumero restringe uma comanda aberta pelo número; itemTermo pesquisa um trecho do nome do item. Cada par de página define o trecho da respectiva lista.
   * Processamento: Mantém os filtros próprios do atendimento: mesa disponível e comanda open. Aplica os termos informados, ordena cada resultado, calcula hasMore para a página solicitada e não grava dados.
   * Saída: Retorna o contexto de localização substituto, com as listas filtradas e paginadas que a página deve redesenhar.
   */
  'comandaRestaurante.atendimento.atualizarLocalizacaoAtendimento': {
    kind: 'qry';
    input: { mesaTermo?: string; comandaNumero?: number; itemTermo?: string; page: number; pageSize: number };
    output: { contextoAtendimento: ContextoAtendimento };
    rules: [];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega a comanda escolhida com a mesa, todas as linhas e o subtotal necessários para conferir e operar o atendimento.
   * Entrada: comandaId é o identificador da comanda selecionada pelo garçom na localização.
   * Processamento: Lê a comanda, a mesa vinculada e todas as linhas, inclusive canceladas, com o nome do item de cardápio. Calcula valorTotal de cada linha conforme valorTotalItemComandaCalculado e subtotal apenas com linhas não canceladas conforme subtotalComandaCalculado; esses valores derivados não são gravados por esta consulta.
   * Saída: Retorna a comanda completa para redesenhar a conferência, identificar a comanda ativa no formulário e disponibilizar a linha selecionada para cancelamento.
   */
  'comandaRestaurante.atendimento.obterComandaAtendimento': {
    kind: 'qry';
    input: { comandaId: string };
    output: { comanda: ComandaAtendimento };
    rules: ['subtotalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  /**
   * Finalidade: Abre a comanda da mesa disponível escolhida e devolve o atendimento pronto para registrar pedidos.
   * Entrada: mesaId preenche o vínculo obrigatório da nova comanda com a mesa selecionada.
   * Processamento: Em transação, verifica que a mesa está disponível conforme mesaDisponivelParaAbrirComanda e recusa outra comanda open para a mesma mesa conforme umaComandaAbertaPorMesa. Gera o número sequencial, cria a comanda em situação open e calcula o subtotal vazio conforme subtotalComandaCalculado.
   * Saída: Retorna a nova comanda com mesa, número, situação, linhas vazias e subtotal, permitindo redesenhar a conferência imediatamente.
   */
  'comandaRestaurante.atendimento.abrirComanda': {
    kind: 'cmd';
    writes: 'Comanda.create';
    input: { mesaId: string };
    output: { comanda: ComandaAtendimento };
    rules: ['mesaDisponivelParaAbrirComanda', 'umaComandaAbertaPorMesa', 'subtotalComandaCalculado'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  /**
   * Finalidade: Inclui o pedido informado na comanda aberta e devolve a conferência integral já atualizada.
   * Entrada: comandaId vincula a nova linha à comanda; itemCardapioId identifica o item escolhido; quantidade registra o volume pedido; observacao registra a orientação opcional de preparo.
   * Processamento: Recusa o lançamento em comanda diferente de open conforme itensSomenteEmComandaAberta. Obtém o preço vigente e o registra na linha conforme precoUnitarioRegistradoNoLancamento, calcula valorTotal conforme valorTotalItemComandaCalculado e recalcula o subtotal da comanda conforme subtotalComandaCalculado.
   * Saída: Retorna a comanda com a nova linha, nome do item, preço registrado, valor calculado e subtotal atualizado, sem exigir nova consulta.
   */
  'comandaRestaurante.atendimento.lancarItem': {
    kind: 'cmd';
    writes: 'ItemComanda.create';
    input: { comandaId: string; itemCardapioId: string; details: { quantidade: number; observacao?: string } };
    output: { comanda: ComandaAtendimento };
    rules: ['itensSomenteEmComandaAberta', 'precoUnitarioRegistradoNoLancamento', 'valorTotalItemComandaCalculado', 'subtotalComandaCalculado'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  /**
   * Finalidade: Cancela a linha escolhida por engano e devolve a comanda com a cobrança recalculada.
   * Entrada: id identifica o item da comanda a transicionar e version protege a operação contra alteração concorrente.
   * Processamento: Executa cancelarItemComanda somente para uma linha launched cuja comanda está open, conforme itemComandaOperacaoSomenteComandaAberta. Mantém a linha no histórico como canceled, calcula seu valor conforme valorTotalItemComandaCalculado e recalcula o subtotal desconsiderando-a conforme subtotalComandaCalculado.
   * Saída: Retorna a comanda completa com a linha marcada como canceled e o subtotal atualizado para conferência imediata.
   */
  'comandaRestaurante.atendimento.cancelarItem': {
    kind: 'cmd';
    writes: 'ItemComanda.cancelarItemComanda';
    input: { id: string; version: number };
    output: { comanda: ComandaAtendimento };
    rules: ['itemComandaOperacaoSomenteComandaAberta', 'valorTotalItemComandaCalculado', 'subtotalComandaCalculado'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/cardapio.defs.ts" enhancement="_blank"/>

/** Detalhes comerciais do item do cardápio exibidos e editados na página. */
export interface DetalhesItemCardapio {
  details: {
    precoVigente: string;
  };
}

/** Dados de um item exibidos no catálogo do cardápio. */
export interface ItemCardapioResumo {
  id: string;
  name: string;
  details: DetalhesItemCardapio;
}

/** Dados persistidos do item selecionado para preenchimento e manutenção do formulário. */
export interface ItemCardapioEdicao {
  id: string;
  version: number;
  name: string;
  details: DetalhesItemCardapio;
}

export interface CardapioContracts {
  /**
   * Finalidade: Carrega a primeira página do catálogo ao abrir a página para o caixa conferir os itens disponíveis e selecionar um para manutenção.
   * Entrada: page informa a página solicitada, assumindo a primeira quando omitida; pageSize limita quantos itens cabem na faixa exibida.
   * Processamento: Lista ItemCardapio em ordem de nome e identificador como desempate estável, aplica a paginação solicitada e compõe id, name e details.precoVigente. Calcula hasMore pela existência de itens depois da página retornada. Nenhuma regra de lançamento ou totalização de comanda se aplica.
   * Saída: Retorna a página já no formato da lista, com itens, página, tamanho da página e indicação de resultados adicionais.
   */
  'comandaRestaurante.cardapio.carregarItensCardapio': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { pagina: { items: ItemCardapioResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca a próxima página do catálogo quando o caixa continua a leitura, sem transferir todos os itens cadastrados.
   * Entrada: page identifica a próxima página a carregar; pageSize informa a quantidade de itens de cada página.
   * Processamento: Lista a página solicitada de ItemCardapio usando a mesma ordenação estável por nome e identificador, projeta id, name e details.precoVigente e calcula hasMore. Nenhuma regra de lançamento ou totalização de comanda se aplica.
   * Saída: Retorna somente a página solicitada para que seus itens sejam anexados ao catálogo já exibido.
   */
  'comandaRestaurante.cardapio.carregarMaisItensCardapio': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { pagina: { items: ItemCardapioResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Obtém o item escolhido no catálogo para preencher o formulário de manutenção.
   * Entrada: id é o identificador do ItemCardapio selecionado pelo caixa.
   * Processamento: Consulta o item pelo identificador e compõe id, version, name e details.precoVigente para edição autorizada. A version é retornada para controle de concorrência. Nenhuma regra de lançamento ou totalização de comanda se aplica.
   * Saída: Retorna o item selecionado no formato que o formulário usa para mostrar e alterar os dados persistidos.
   */
  'comandaRestaurante.cardapio.obterItemCardapio': {
    kind: 'qry';
    input: { id: string };
    output: { item: ItemCardapioEdicao };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra um item com nome e preço vigente para uso operacional no cardápio.
   * Entrada: name é o nome pelo qual a equipe localiza o item; details.precoVigente é o preço atualmente cobrado.
   * Processamento: Cria ItemCardapio com o nome e o preço vigente recebidos e compõe o registro persistido, incluindo id e version gerados. Não cria ItemComanda, nem registra preço de lançamento ou executa regras de subtotal, total ou valor de item.
   * Saída: Retorna o item criado e persistido para redesenhar imediatamente o formulário; o catálogo é recarregado para refletir a inclusão.
   */
  'comandaRestaurante.cardapio.cadastrarItemCardapio': {
    kind: 'cmd';
    writes: 'ItemCardapio.create';
    input: { name: string; details: DetalhesItemCardapio };
    output: { item: ItemCardapioEdicao };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Atualiza o nome e o preço vigente do item selecionado para manter o catálogo usado pela operação.
   * Entrada: id e version identificam a versão persistida a alterar; name e details.precoVigente são os valores informados pelo caixa.
   * Processamento: Atualiza o ItemCardapio por id somente se a version recebida corresponder à versão atual, recusando sobrescrita concorrente, e compõe a nova versão persistida. Não altera ItemComanda já lançado nem aplica regras de preço de lançamento, subtotal, total ou valor de ItemComanda.
   * Saída: Retorna o registro atualizado, incluindo a nova version, para redesenhar o formulário sem nova consulta; o catálogo é recarregado para refletir a alteração.
   */
  'comandaRestaurante.cardapio.atualizarItemCardapio': {
    kind: 'cmd';
    writes: 'ItemCardapio.update';
    input: { id: string; version: number; name: string; details: DetalhesItemCardapio };
    output: { item: ItemCardapioEdicao };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/fechamento.defs.ts" enhancement="_blank"/>

/** Dados da mesa vinculada à comanda, apresentados para o caixa localizar a cobrança. */
export interface MesaResumo {
  code: string;
}

/** Resumo de uma comanda ainda aberta para localização e seleção no fechamento. */
export interface ComandaAbertaResumo {
  id: string;
  number: number;
  mesaId: string;
  status: 'open' | 'closed';
  details: ComandaResumoDetails;
  mesa: MesaResumo;
}

/** Valores calculados exibidos no resumo de uma comanda aberta. */
export interface ComandaResumoDetails {
  readonly totalComanda: string;
}

/** Identificação do item de cardápio associada a uma linha da comanda. */
export interface ItemCardapioNaComanda {
  name: string;
}

/** Dados de quantidade, observação, preço registrado e total calculado da linha conferida pelo caixa. */
export interface ItemComandaDetailsParaFechamento {
  details: {
    quantidade: number;
    observacao?: string;
    precoUnitario: string;
  };
  readonly valorTotal: string;
}

/** Linha válida da comanda que compõe a cobrança a conferir. */
export interface ItemComandaParaFechamento {
  status: 'launched' | 'canceled';
  itemCardapioId: string;
  details: ItemComandaDetailsParaFechamento;
  itemCardapio: ItemCardapioNaComanda;
}

/** Desconto, pagamento e totais da comanda mostrados e informados no fechamento. */
export interface ComandaDetailsParaFechamento {
  details: {
    discountAmount?: string;
    paymentMethod?: 'cash' | 'debitCard' | 'creditCard' | 'pix';
  };
  readonly subtotal: string;
  readonly totalComanda: string;
}

/** Indicador de disponibilidade da mesa vinculada após a situação atual da comanda. */
export interface MesaNoFechamento {
  readonly disponivel: boolean;
}

/** Comanda selecionada com linhas válidas, totais calculados, dados de pagamento e indicador da mesa para conferência e fechamento. */
export interface ComandaParaFechamento {
  id: string;
  version: number;
  number: number;
  status: 'open' | 'closed';
  details: ComandaDetailsParaFechamento;
  items: ItemComandaParaFechamento[];
  mesa: MesaNoFechamento;
}

export interface FechamentoContracts {
  /**
   * Finalidade: Carrega o fechamento com as comandas abertas para localização e, quando houver contexto, a cobrança completa que o caixa irá conferir.
   * Entrada: comandaId identifica a comanda recebida no contexto. number e mesaCode restringem a localização inicial. page e pageSize definem a janela da lista de comandas abertas.
   * Processamento: Filtra a lista obrigatoriamente por situação open, aplica número e código de mesa quando informados, ordena de forma estável e entrega a janela paginada. Compõe o código da mesa e calcula o total de cada resumo conforme valorTotalItemComandaCalculado, subtotalComandaCalculado e totalComandaCalculado. Se comandaId identificar uma comanda aberta, compõe suas linhas launched, nomes do cardápio, pagamento, totais calculados e disponibilidade calculada da mesa; campos derivados são apenas calculados.
   * Saída: Retorna uma lista paginada e enxuta pronta para localizar a conta e, opcionalmente, a comanda contextual completa para preencher revisão, pagamento e ação de fechamento.
   */
  'comandaRestaurante.fechamento.carregarFechamento': {
    kind: 'qry';
    input: { comandaId?: string; number?: number; mesaCode?: string; page: number; pageSize: number };
    output: { openComandas: { items: ComandaAbertaResumo[]; page: number; pageSize: number; hasMore: boolean }; selectedComanda?: ComandaParaFechamento };
    rules: ['subtotalComandaCalculado', 'totalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Substitui a lista de localização pelas comandas abertas que correspondem ao número ou à mesa procurados pelo caixa.
   * Entrada: number filtra pelo número da comanda e mesaCode pelo código da mesa. page e pageSize definem a primeira janela resultante da busca ou troca de filtros.
   * Processamento: Restringe o resultado a comandas open, combina os filtros informados e ordena antes de paginar. Para cada resumo, compõe a mesa e calcula totalComanda pelas regras valorTotalItemComandaCalculado, subtotalComandaCalculado e totalComandaCalculado, sem registrar valores derivados.
   * Saída: Retorna a janela paginada de resumos para substituir a lista que o caixa está pesquisando.
   */
  'comandaRestaurante.fechamento.buscarComandasAbertas': {
    kind: 'qry';
    input: { number?: number; mesaCode?: string; page: number; pageSize: number };
    output: { openComandas: { items: ComandaAbertaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['subtotalComandaCalculado', 'totalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca a próxima janela das comandas abertas da localização atual sem recarregar os resumos já exibidos.
   * Entrada: number e mesaCode repetem os filtros ativos. page e pageSize identificam a próxima janela solicitada.
   * Processamento: Aplica os mesmos filtros obrigatórios de situação open, número e mesa, ordena de forma estável e pagina a próxima janela. Compõe mesa e total calculado conforme valorTotalItemComandaCalculado, subtotalComandaCalculado e totalComandaCalculado.
   * Saída: Retorna uma página adicional de resumos para ser anexada à lista de comandas abertas.
   */
  'comandaRestaurante.fechamento.carregarMaisComandasAbertas': {
    kind: 'qry';
    input: { number?: number; mesaCode?: string; page: number; pageSize: number };
    output: { openComandas: { items: ComandaAbertaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['subtotalComandaCalculado', 'totalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Obtém a comanda aberta selecionada pelo caixa, já composta para conferência, recebimento e fechamento.
   * Entrada: id é o identificador da comanda escolhida na lista de comandas abertas.
   * Processamento: Lê a comanda aberta autorizada, inclui somente itens launched, associa o nome de cada ItemCardapio e calcula valorTotal, subtotal e totalComanda segundo valorTotalItemComandaCalculado, subtotalComandaCalculado e totalComandaCalculado. Também calcula o indicador de disponibilidade da mesa, sem gravar nenhum campo derivado.
   * Saída: Retorna versão, situação, linhas válidas, desconto, forma de pagamento, totais e indicador da mesa para os organismos de revisão, pagamento e fechamento.
   */
  'comandaRestaurante.fechamento.obterComandaParaFechamento': {
    kind: 'qry';
    input: { id: string };
    output: { comanda: ComandaParaFechamento };
    rules: ['subtotalComandaCalculado', 'totalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Registra o desconto e o pagamento, fecha a comanda e confirma que sua mesa foi liberada.
   * Entrada: id e version identificam a comanda aberta e protegem contra fechamento concorrente. discountAmount é o desconto opcional. paymentMethod é a forma de pagamento obrigatória do fechamento.
   * Processamento: Em transação, recompõe os itens launched e recalcula valorTotal, subtotal e total pelas regras valorTotalItemComandaCalculado, subtotalComandaCalculado e totalComandaCalculado. Recusa pagamento ausente por pagamentoObrigatorioNoFechamento e desconto superior ao subtotal por descontoNaoExcedeSubtotal. Com a versão válida, grava o payload da transição fecharComanda, muda a situação para closed e libera a mesa segundo fechamentoLiberaMesa.
   * Saída: Retorna a comanda fechada, com linhas, desconto, pagamento, totais recalculados e indicador de mesa disponível, para redesenhar imediatamente a confirmação.
   */
  'comandaRestaurante.fechamento.fecharComandaPaga': {
    kind: 'cmd';
    writes: 'Comanda.fecharComanda';
    input: { id: string; version: number; details: { discountAmount?: string; paymentMethod: 'cash' | 'debitCard' | 'creditCard' | 'pix' } };
    output: { comanda: ComandaParaFechamento };
    rules: ['pagamentoObrigatorioNoFechamento', 'descontoNaoExcedeSubtotal', 'fechamentoLiberaMesa', 'subtotalComandaCalculado', 'totalComandaCalculado', 'valorTotalItemComandaCalculado'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/inicio.defs.ts" enhancement="_blank"/>

/** Indicadores consolidados da operação do restaurante para a visão geral. */
export interface ResumoOperacional {
  readonly mesasDisponiveis: number;
  readonly valorComandasAbertas: number;
}

export interface InicioContracts {
  /**
   * Finalidade: Carrega os indicadores consolidados que caixa e garçom usam para consultar rapidamente a disponibilidade das mesas e o valor ainda em atendimento.
   * Entrada: Não recebe parâmetros: o resumo considera toda a operação da organização acessível ao ator.
   * Processamento: Conta as mesas cuja disponibilidade calculada é verdadeira. Filtra as comandas com situação aberta e calcula o valor das comandas em aberto pela soma de seus subtotais; cada subtotal é derivado apenas dos valores totais dos itens não cancelados, conforme a regra subtotalComandaCalculado. Retorna somente os indicadores, sem transferir listas de mesas, comandas ou itens.
   * Saída: Retorna o resumo operacional já agregado para renderização direta dos destaques da página, com a quantidade de mesas disponíveis e o valor total das comandas abertas.
   */
  'comandaRestaurante.inicio.carregarResumoOperacional': {
    kind: 'qry';
    input: {};
    output: { resumoOperacional: ResumoOperacional };
    rules: ['subtotalComandaCalculado'];
    access: { actors: ['caixa', 'garcom']; grants: ['garcomAtendimentoComandas', 'caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/mesas.defs.ts" enhancement="_blank"/>

/** Dados completos de uma mesa necessários para exibir a lista da casa, preencher a seleção no formulário e redesenhar a página após manutenção. */
export interface MesaResumo {
  id: string;
  version: number;
  code: string;
  details: {
    readonly disponivel: boolean;
  };
}

export interface MesasContracts {
  /**
   * Finalidade: Carrega as mesas da casa para o caixa consultar seus códigos, conferir a disponibilidade e selecionar uma mesa para manutenção.
   * Entrada: Não recebe parâmetros; considera o escopo organizacional autorizado para o caixa.
   * Processamento: Obtém as mesas visíveis ao caixa e as ordena pelo código. Para cada mesa, compõe identificador, versão, código e disponibilidade. A disponibilidade é derivada pela inexistência de comanda aberta vinculada e é calculada nesta consulta, sem ser gravada. A lista representa o conjunto físico de mesas da casa e é carregada integralmente, sem paginação.
   * Saída: Retorna as mesas no formato consumido pela lista e pelo formulário selecionado. A versão acompanha cada registro para permitir atualização concorrente segura.
   */
  'comandaRestaurante.mesas.carregarMesas': {
    kind: 'qry';
    input: {};
    output: { mesas: MesaResumo[] };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra uma mesa para a operação do restaurante e devolve seu estado completo para redesenhar a página.
   * Entrada: code é o código da nova mesa informado pelo caixa.
   * Processamento: Cria a mesa com o código recebido, aplicando as validações de criação e a unicidade do código no repositório. Depois compõe o identificador, a versão, o código e a disponibilidade. A disponibilidade é derivada da inexistência de comanda aberta vinculada, é calculada no retorno e não é gravada pelo comando.
   * Saída: Retorna a mesa criada no formato usado pela lista e pelo formulário, permitindo inseri-la na lista sem uma segunda chamada.
   */
  'comandaRestaurante.mesas.criarMesa': {
    kind: 'cmd';
    writes: 'Mesa.create';
    input: { code: string };
    output: { mesa: MesaResumo };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  /**
   * Finalidade: Atualiza o código da mesa selecionada e devolve seu estado completo e corrente para redesenhar a página.
   * Entrada: id identifica a mesa selecionada, version protege a gravação contra atualização concorrente e code é o código informado pelo caixa.
   * Processamento: Localiza a mesa pelo identificador, confere a versão recebida e atualiza seu código, aplicando as validações de manutenção e a unicidade do código. Em seguida compõe o identificador, a nova versão, o código e a disponibilidade derivada. A disponibilidade é calculada pela inexistência de comanda aberta vinculada e não é armazenada por este comando.
   * Saída: Retorna a mesa atualizada no formato da lista e do formulário, permitindo atualizar a linha e manter a versão corrente sem nova consulta.
   */
  'comandaRestaurante.mesas.atualizarMesa': {
    kind: 'cmd';
    writes: 'Mesa.update';
    input: { id: string; version: number; code: string };
    output: { mesa: MesaResumo };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}
